import logging
from taf.analyzer.pcap.exceptions import PacketNotFound
from taf.internal.aliasing import aliasing_scope
from taf.analyzer.pcap.tshark_command import TsharkCommand
from taf.analyzer.pcap.pcap_parser import PcapParser


class pcap(object):

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    lookup_handler, configured_pcap_parser = aliasing_scope(
        name=__name__, lookup_arg='pcap_parser', lookup_type=PcapParser)

    """
    This library is used for analyzing pcap file.
    Implemented based on tshark (Wireshark tool) to loading pcap file.
    User can specify some options of tshark when loading pcap file.
    Supported getting specified field values of pcap packets.

    Keep compatibility with "check_cap.py" and "taf.ul.parser.pcap".
    More information, you can refer to under confluence page.
    https://confluence.ext.net.nokia.com/pages/viewpage.action?spaceKey=5GRANHZ&title=taf.analyzer.pcap
    """

    def setup(self,
              infile,
              display_filter=None,
              extension=None,
              override_preference_setting=None,
              disable_all_name_resolutions=None,
              flush_standard_output=None,
              tshark_path=None,
              alias=None):
        """
        Setup pcap parser with tshark command options.

        :param infile: TcpDump cap file.
        :type infile: str
        :param display_filter: packet display filter in Wireshark display filter,
            e.g x2ap_5g18a_3_01.e212.mcc == 311 and x2ap_5g18a_3_01.e212.mnc == 489
        :type display_filter: str
        :param extension: eXtension options.
            e.g "lua_script:generated_luashark/luashark.lua"
        :type extension: str
        :param override_preference_setting:  override preference setting.
            e.g {" esp.enable_null_encryption_decode_heuristic": true, "esp.enable_encryption_decode": true}
        :type override_preference_setting: dictionary
        :param disable_all_name_resolutions: disable all name resolutions (default: True).
        :type disable_all_name_resolutions: bool
        :param flush_standard_output: flush standard output after each packet (default: True).
        :type flush_standard_output: bool
        :param tshark_path: specified tshark path.
        :type tshark_path: str
        :param alias: pcap parser alias name.
        :type alias: str
        :return: pcap_parser instance.
        :rtype: PcapParser
        """
        configured_parser = PcapParser()
        command = TsharkCommand.from_tshark_options(infile=infile,
                                                    display_filter=display_filter,
                                                    extension=extension,
                                                    override_preference_setting=override_preference_setting,
                                                    disable_all_name_resolutions=disable_all_name_resolutions,
                                                    flush_standard_output=flush_standard_output,
                                                    tshark_path=tshark_path)
        configured_parser.setup_tshark_command(command)
        self.configured_pcap_parser.add(configured_parser, alias)

    @lookup_handler.implicit_lookup
    def get_packets(self, filter=None, override_original_expression=False, pcap_parser=None):
        """
        Get filtered packet instances
        :param filter: Wireshark filter expression.
        :param override_original_expression: override original expression, default False.
        :type filter: str
        :param pcap_parser: pcap parser alias name.
        :type pcap_parser: str
        :return: packets list
        :rtype: list
        """
        if override_original_expression is True:
            pcap_parser.config_filter(filter=None)

        pcap_parser.config_filter(filter=filter)
        packets = pcap_parser.get_packets()
        if not packets:
            raise PacketNotFound

        return packets

    @lookup_handler.implicit_lookup
    def get_field_value(self, field_name, fmt="show", filter=None, pcap_parser=None):
        """
        Get specified field's values from filtered packets.
        :param field_name: Wireshark field expression.
        :type field_name: str
        :param fmt: return value format, default is "show" e.g "show", "value" and "showname".
        :type fmt: str
        :param filter: Wireshark filter expression.
        :type filter: str
        :param pcap_parser: pcap parser alias name.
        :type pcap_parser: str
        :return: field value list of filtered packets.
            e.g if field "PCMD_5G.pcap" has 3 fields in one packet, the return list will be like under:
            [['111', '248', '203'],  # 2 field values belong to a packet
             ['111', '207', '214'],
             ['10', '9', '18'],
             ['111', '207', '5'],
             ['10', '9', '207'],
             ['10', '9', '18']]
        :rtype: list
        """
        pcap_parser.config_filter(filter=filter)
        return pcap_parser.get_field_value_by_name(field_name=field_name, attribute=fmt)

    def read_cap(self, cap_file, alias=None, **kwargs):
        """
        Deprecated keyword, it is compatible with "check_cap.py".
        load Wireshark file for checking fields
        :param cap_file: Tcpdump cap file.
        :type cap_file: str
        :param alias: pcap parser alias name.
        :type alias: str
        :param kwargs: tshark options:
            display_filter: A display (Wireshark) filter to apply on the cap before reading it.
            decryption_key: Optional key used to encrypt and decrypt captured traffic.
            encryption_type: Standard of encryption used in captured traffic (must be either 'WEP', 'WPA-PWD', or
                'WPA-PWK'. Defaults to WPA-PWK).
            tshark_path: Specified the path of tshark binary.
            override_prefs: A dictionary of tshark preferences to override, {PREFERENCE_NAME: PREFERENCE_VALUE}.
            X: <key>:<value> eXtension options, see the man page for details.
        :return: NA
        """
        logging.info("This Keyword will be deprecated in future, please use setup/get_packets/get_field_value.")
        configured_parser = PcapParser()
        command = TsharkCommand.from_pyshark_params(cap_file=cap_file,
                                                    **kwargs)
        configured_parser.setup_tshark_command(command)
        self.configured_pcap_parser.add(configured_parser, alias)

    @lookup_handler.implicit_lookup
    def check_expression(self, condition_expression, pcap_parser=None):
        """
        Deprecated keyword, compatible with "check_cap.py".
        check if expression is matched in packets.

        :param condition_expression: Wireshark filter expression.
        :type condition_expression: str
        :param pcap_parser: pcap parser alias name.
        :type pcap_parser: str
        :return: filtered packets, if check failed, will raise exception.
        :rtype: list
        """
        logging.info("This Keyword will be deprecated in future, please use setup/get_packets/get_field_value.")
        pcap_parser.config_filter(filter=None)
        return self.get_packets(filter=condition_expression, pcap_parser=pcap_parser)

    @lookup_handler.implicit_lookup
    def get_element_value(self, element_expression, element_idx=0, default_value=False, raw_data=True,
                          condition_expression=None, pcap_parser=None):
        """
        Deprecated keyword, compatible with "check_cap.py".
        get element value by element_expression(e.g., x2ap_5g18a_3_01.id) ,idx and condition_expression.

        :param element_expression: field name of element.
        :type element_expression: str
        :param element_idx: index of element, if one packet have multiple same element by field name,
        can use idx to specify one
        :type element_idx: int
        :param default_value: default value in packet, if it is False, return raw value.
        :type default_value: bool
        :param raw_data: raw data in packet, if it is True, return decimal value string.
        :type raw_data: bool
        :param condition_expression: string condition to filter.
            (e.g., x2ap_5g18a_3_01.id[0] == 111 and x2ap_5g18a_3_01.id[1] == 248)
        :type condition_expression: str
        :param pcap_parser: pcap parser alias name.
        :type pcap_parser: str
        :return: list of values
        :rtype: list
        """
        logging.info("This Keyword will be deprecated in future, please use setup/get_packets/get_field_value.")
        pcap_parser.config_filter(filter=None)
        pcap_parser.config_filter(filter=condition_expression)
        if default_value:
            attribute = "show"
        elif raw_data:
            attribute = "value"
        else:
            attribute = "showname"

        field_values = pcap_parser.get_field_value_by_name(field_name=element_expression, attribute=attribute)
        return [each_value[int(element_idx)] for each_value in field_values]

    def load_pcap_file(self, pcap_file, tshark_path=None, luashark_path=None, command_template=None, alias=None):
        """
        Deprecated keyword, compatible with "taf.ul.parser.pcap"
        Load packets from pcap file, it contains two steps: 1.Convert pcap to pdml. 2.Read packets from pdml file.

        :param pcap_file: path of pcap file
        :type pcap_file: str
        :param tshark_path: path of tshark executable
        :type tshark_path: str
        :param luashark_path: path of luashark file
        :type luashark_path: str
        :param command_template: tshark command template of pcap to pdml conversion
        :type command_template: str
        :param alias: pcap parser alias name.
        :type alias: str
        :return: all packets in the pcap log with PdmlLogEntry format
        :rtype: list(generator(PdmlLogEntry))
        """
        logging.info("This Keyword will be deprecated in future, please use setup/get_packets/get_field_value.")
        configured_parser = PcapParser()
        command = TsharkCommand.from_parser_params(pcap_file=pcap_file,
                                                   tshark_path=tshark_path,
                                                   luashark_path=luashark_path,
                                                   command_template=command_template)
        configured_parser.setup_tshark_command(command)
        self.configured_pcap_parser.add(configured_parser, alias)

    @lookup_handler.implicit_lookup
    def filter_packets_by_expression(self, filter_expression=None, pcap_parser=None):
        """
        Deprecated keyword, it is compatible with "taf.ul.parser.pcap"
        Filter packets based on the required expression. Return PDML entries meet the expression.

        :param filter_expression: Wireshark filter expression
        :type filter_expression: str
        :param pcap_parser: pcap parser alias name.
        :type pcap_parser: str
        :return: NA
        """
        logging.info("This Keyword will be deprecated in future, please use setup/get_packets/get_field_value.")
        pcap_parser.config_filter(filter=None)
        pcap_parser.config_filter(filter=filter_expression)

    @lookup_handler.implicit_lookup
    def get_field_value_by_name(self, field_name, attribute_name="show", pcap_parser=None, **kwargs):
        """
        Deprecated keyword, compatible with "taf.ul.parser.pcap"
        Get field values from the packets by the specified field name.

        :param field_name: Wireshark field name in a packet
        :type field_name: str
        :param attribute_name: attribute of packet field, e.g "show", "value", or "showname", default is "show".
         Details about the attribute can be found in
         https://confluence.int.net.nokia.com/display/5GRANHZ/taf.ul.parser.pcap.
         Note that "frame" related fields do not have "value" attribute.
        :type attribute_name: str
        :param pcap_parser: pcap parser alias name.
        :type pcap_parser: str
        :param kwargs: for compatibility with "taf.ul.parser.pcap" keyword.
        :return: field value list
        :rtype: list
        """
        logging.info("This Keyword will be deprecated in future, please use setup/get_packets/get_field_value.")
        field_values = pcap_parser.get_field_value_by_name(field_name=field_name, attribute=attribute_name)
        return pcap_parser.extend_one_element_list(field_values)

    @lookup_handler.implicit_lookup
    def get_field_value_by_xpath(self, xpath, attribute_name="show", pcap_parser=None, **kwargs):
        """
        Deprecated keyword, compatible with "taf.ul.parser.pcap"
        Return attribute values for the specified field xpath.

        :param xpath: field xpath in a packet.
        :type xpath: str
        :param attribute_name: attribute of packet field, value can be "show", "value", or "showname",
         default is "show".
         Note that "frame" related fields do not have "value" attribute
        :type attribute_name: str
        :param pcap_parser: pcap parser alias name.
        :type pcap_parser: str
        :param kwargs: for compatibility with "taf.ul.parser.pcap" keyword.
        :return: field value list
        :rtype: list
        """
        logging.info("This Keyword will be deprecated in future, please use setup/get_packets/get_field_value.")
        field_values = pcap_parser.get_field_value_by_xpath(field_xpath=xpath, attribute=attribute_name)
        return pcap_parser.extend_one_element_list(field_values)
